import * as React from "react"
import { cn } from "cn"

function FilterSelect({
  className,
  ...props
}: React.ComponentProps<"select">) {
  return (
    <select
      data-slot="filter-select"
      className={cn(
        "h-8 rounded-lg border border-input bg-transparent px-2 text-sm outline-none focus-visible:ring-3 focus-visible:ring-ring/50 dark:bg-input/30",
        className
      )}
      {...props}
    />
  )
}

function MultiSelect({
  className,
  ...props
}: React.ComponentProps<"select">) {
  return (
    <FilterSelect
      data-slot="multi-select"
      multiple
      className={cn("h-auto min-h-20 py-1", className)}
      {...props}
    />
  )
}

function DatePicker({
  className,
  ...props
}: Omit<React.ComponentProps<"input">, "type">) {
  return (
    <input
      data-slot="date-picker"
      type="date"
      className={cn(
        "h-8 rounded-lg border border-input bg-transparent px-2 text-sm outline-none focus-visible:ring-3 focus-visible:ring-ring/50 dark:bg-input/30",
        className
      )}
      {...props}
    />
  )
}

export { DatePicker, FilterSelect, MultiSelect }
